(()=>{let previous=0,queued=false;const report=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;const board=document.getElementById('board'),note=document.querySelector('.board-note');if(!board)return;const height=Math.ceil((note||board).getBoundingClientRect().bottom+24);if(Math.abs(height-previous)<2)return;previous=height;parent.postMessage({type:'erp-activity-height',height},location.origin)})};new ResizeObserver(report).observe(document.getElementById('board'));window.addEventListener('load',report);report()})();
